// Bundle Cloudflare Puppeteer into one source string that the Worker
// JavaScript backend can install in a Dynamic Worker.

import { mkdir, writeFile } from "node:fs/promises";
import { builtinModules } from "node:module";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { build } from "esbuild";

const here = dirname(fileURLToPath(import.meta.url));
const output = resolve(here, "generated.ts");

const nodeBuiltins = new Set(builtinModules.map((specifier) => specifier.replace(/^node:/, "")));

const result = await build({
  entryPoints: [resolve(here, "runtime.ts")],
  bundle: true,
  write: false,
  minify: true,
  format: "esm",
  target: "es2022",
  platform: "neutral",
  conditions: ["workerd", "worker", "import"],
  mainFields: ["module", "main"],
  define: {
    "process.env.WS_NO_BUFFER_UTIL": "true",
    "process.env.WS_NO_UTF_8_VALIDATE": "true",
  },
  metafile: true,
  external: ["workspace-plugin-bindings.js", "cloudflare:workers", "node:*"],
  plugins: [
    {
      name: "node-builtins",
      setup(pluginBuild) {
        pluginBuild.onResolve({ filter: /.*/ }, (args) =>
          nodeBuiltins.has(args.path) ? { path: `node:${args.path}`, external: true } : undefined,
        );
      },
    },
  ],
});

const bundled = result.outputFiles?.[0]?.text;
if (bundled === undefined) throw new Error("Puppeteer bundle produced no output");
if (new TextEncoder().encode(bundled).byteLength > 768 * 1024) {
  throw new Error("Puppeteer bundle exceeds the 768 KiB plugin budget");
}

const externalImports = Object.values(result.metafile.outputs)
  .flatMap((entry) => entry.imports)
  .filter((entry) => entry.external)
  .map((entry) => entry.path);
const unsupportedImport = externalImports.find(
  (specifier) => specifier !== "workspace-plugin-bindings.js" && !specifier.startsWith("node:"),
);
if (unsupportedImport !== undefined) {
  throw new Error(`Puppeteer bundle left unsupported import ${JSON.stringify(unsupportedImport)}`);
}

await mkdir(dirname(output), { recursive: true });
await writeFile(
  output,
  [
    "// Generated by build-bundle.mjs. Do not edit.",
    `export default ${JSON.stringify(bundled)};`,
    "",
  ].join("\n"),
);
console.log(`Wrote ${output} (${new TextEncoder().encode(bundled).byteLength} bytes)`);
